if(!exists('simulate_asset_pool'))library(creditratingsystem)
spa_D<-'2023-01-01';spa_dates<-list('2023-07-01','2024-01-01')
spa_asset<-function(id='a',group='g')list(asset_id=id,asset_class='AUTO_LOAN',invoice_id=NULL,obligor_id=group,default_group_id=group,seller_id='seller',servicer_id='service',currency='EUR',observed_at=spa_D,known_at=spa_D,origination_date='2022-01-01',balance_date=spa_D,principal_balance=100,schedule=list(list(date=spa_dates[[1]],principal_due=40,interest_due=5),list(date=spa_dates[[2]],principal_due=60,interest_due=3)),overdue_days=0,disputed=FALSE,dilution_reserve=0,recourse='NONE',collateral_allocations=list())
spa_assignment<-function(id='m',aid='a',start=spa_D,price=100)list(assignment_id=id,pool_id='pool',asset_id=aid,known_at=spa_D,effective_from=start,effective_until=NULL,share=1,purchase_price=price,purchase_priority=1)
spa_fixture<-function(assets=list(spa_asset()),assignments=list(spa_assignment()),revolving=FALSE){
 p<-list(profile_id='p',version='1',known_at=spa_D,currency='EUR',product_kind='ABS',pool_mode=if(revolving)'REVOLVING'else'STATIC',allowed_asset_classes=list('AUTO_LOAN'),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE'),revolving_until=if(revolving)spa_dates[[2]]else NULL)
 pool<-build_credit_asset_pool(assets,assignments,p,'pool',spa_D,spa_D)$value
 contract<-list(contract_id='c',version='1',scenario_ids=list('s'),weights=list(1),dates=spa_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT',default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',dilution_treatment='PROPORTIONAL_REMAINING_SCHEDULE',reinvestment_funding='PRINCIPAL_CASH_ONLY',initial_reinvestment_cash=0)
 gp<-ap<-innov<-list();for(g in sort(unique(vapply(assets,function(a)a$default_group_id,''))))for(d in spa_dates){gp[[length(gp)+1L]]<-list(scenario_id='s',default_group_id=g,date=d,conditional_pd=0,default_channel=paste0('default-',g));innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('default-',g),uniform=.5)}
 for(a in assets)for(d in spa_dates){ap[[length(ap)+1L]]<-list(scenario_id='s',asset_id=a$asset_id,date=d,conditional_prepayment_probability=0,prepayment_channel=paste0('prepay-',a$asset_id),dilution_fraction=0,recovery_fraction=.4,recovery_delay_days=30,recovery_cost=5,servicing_cost=0,interest_multiplier=1,overdue_days=0,disputed=FALSE);innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('prepay-',a$asset_id),uniform=.5)}
 list(asset_pool=pool,scenario_contract=contract,obligor_paths=gp,asset_paths=ap,shared_innovations=innov)
}
spa_run<-function(f)do.call(simulate_asset_pool,f)$value
spa_total<-function(r,key)sum(vapply(r$cashflows,function(c)c[[key]],0.))
spa_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
r<-spa_run(spa_fixture());stopifnot(spa_total(r,'principal_available')==100,spa_total(r,'interest_available')==8,r$ending_states[[1]]$terminal_complete,all(vapply(r$asset_events,function(x)x$principal_conservation_residual==0,TRUE)))
f<-spa_fixture(list(spa_asset(),spa_asset('b')),list(spa_assignment(),spa_assignment('b','b')));f$obligor_paths[[1]]$conditional_pd<-1;r<-spa_run(f);stopifnot(sum(vapply(r$asset_events,function(e)e$default_ead,0.))==200,spa_total(r,'interest_available')==0,spa_total(r,'principal_available')==0,spa_total(r,'recovery_gross')==80,spa_total(r,'workout_cost')==10,tail(r$cashflows,1)[[1]]$cumulative_modeled_credit_loss==130,r$ending_states[[1]]$terminal_complete,sum(vapply(r$group_events,function(e)e$new_default,TRUE))==1,Filter(function(c)c$recovery_gross>0,r$cashflows)[[1]]$date=='2023-07-31')
f<-spa_fixture();f$asset_paths[[1]]$conditional_prepayment_probability<-1;r<-spa_run(f);stopifnot(r$asset_events[[1]]$event=='PREPAYMENT',spa_total(r,'principal_available')==100,spa_total(r,'interest_available')==5);f$obligor_paths[[1]]$conditional_pd<-1;r<-spa_run(f);stopifnot(r$asset_events[[1]]$event=='DEFAULT',spa_total(r,'interest_available')==0)
f<-spa_fixture();f$asset_paths[[1]]$dilution_fraction<-.25;r<-spa_run(f);stopifnot(spa_total(r,'principal_available')==75,spa_total(r,'interest_available')==6,tail(r$cashflows,1)[[1]]$cumulative_dilution_loss==25);f$asset_paths[[1]]$dilution_fraction<-1;r<-spa_run(f);stopifnot(r$asset_events[[1]]$event=='DILUTED',r$ending_states[[1]]$terminal_complete)
a<-spa_asset();b<-spa_asset('b','h');a$schedule<-list(list(date=spa_dates[[1]],principal_due=100,interest_due=10));b$schedule<-list(list(date=spa_dates[[1]],principal_due=50,interest_due=5),list(date=spa_dates[[2]],principal_due=50,interest_due=2));f<-spa_fixture(list(a,b),list(spa_assignment(),spa_assignment('next','b',spa_dates[[1]],50)),TRUE);r<-spa_run(f);first<-r$cashflows[[1]];last<-tail(r$cashflows,1)[[1]];stopifnot(first$principal_collections==100,first$purchase_cash==50,first$closing_reinvestment_cash==50,first$principal_available==0,first$interest_available==10,last$principal_available==100,last$interest_available==2,r$acquisitions[[1]]$acquired_principal==50,r$ending_states[[1]]$terminal_complete)
f<-spa_fixture(list(spa_asset(),spa_asset('b','h')),list(spa_assignment(),spa_assignment('next','b',spa_dates[[1]],50)),TRUE);r<-spa_run(f);stopifnot(r$acquisitions[[1]]$reason=='INSUFFICIENT_PRINCIPAL_CASH',spa_total(r,'principal_available')==100);f$asset_paths[[3]]$disputed<-TRUE;stopifnot(spa_run(f)$acquisitions[[1]]$reason=='ACQUISITION_ELIGIBILITY_FAILED')
f<-spa_fixture();f$obligor_paths[[1]]$conditional_pd<-1;f$asset_paths[[1]]$recovery_delay_days<-1000;r<-spa_run(f);stopifnot(!r$ending_states[[1]]$terminal_complete,r$ending_states[[1]]$pending_recoveries[[1]]$gross==40,spa_total(r,'recovery_gross')==0)
f<-spa_fixture();f$shared_innovations[[length(f$shared_innovations)+1L]]<-list(scenario_id='s',date=spa_dates[[1]],channel_id='unused',uniform=.5);spa_error('STRUCTURED_ASSET_PATH',spa_run(f));f<-spa_fixture();f$scenario_contract$dates<-spa_dates[2];spa_error('STRUCTURED_CALENDAR',spa_run(f));f<-spa_fixture();f$asset_paths[[1]]$conditional_prepayment_probability<-1.1;spa_error('STRUCTURED_INPUT',spa_run(f))
cat('Native shared-default, prepayment, dilution and financed reinvestment oracles PASS\n')

f<-spa_fixture();f$context<-list(conditioning='TTC');spa_error('TARGET_MISMATCH',spa_run(f));f$context<-list(horizon=1);spa_error('TARGET_MISMATCH',spa_run(f));f$context<-list(conditioning='PIT',horizon=365,time_unit='days');stopifnot(spa_run(f)$origin==spa_D)

f<-spa_fixture();f$asset_pool<-list(sha256='not-a-binding');spa_error('STRUCTURED_ARTIFACT',spa_run(f))
